import re


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }
    tokenizer = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/():,=<>]"
    )

    def integer(text):
        # Chunk conversion also supports literals beyond Python's digit limit.
        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]
        value = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return sign * value

    def parse(formula):
        nodes = []
        operators = []
        comma_counts = []
        expecting_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for token in tokenizer.findall(formula):
            if token[0].isdigit():
                nodes.append(integer(token))
                expecting_operand = False
            elif token in functions:
                operators.append(token)
                expecting_operand = True
            elif token[0].isalpha():
                nodes.append(("ref", token))
                expecting_operand = False
            elif token == "(":
                operators.append(token)
                comma_counts.append(0)
                expecting_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                comma_counts[-1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                argument_count = comma_counts.pop() + 1
                if operators and operators[-1] in functions:
                    name = operators.pop()
                    arguments = tuple(nodes[-argument_count:])
                    del nodes[-argument_count:]
                    nodes.append((name, arguments))
                expecting_operand = False
            elif token == "-" and expecting_operand:
                operators.append("neg")
            else:
                while (
                    operators
                    and operators[-1] in precedence
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expecting_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_nodes(arguments):
        for argument in arguments:
            if isinstance(argument, tuple) and argument[0] == ":":
                first = argument[1][1]
                second = argument[2][1]
                c1, c2 = sorted((ord(first[0]), ord(second[0])))
                r1, r2 = sorted((int(first[1:]), int(second[1:])))
                for row in range(r1, r2 + 1):
                    for column in range(c1, c2 + 1):
                        name = chr(column) + str(row)
                        if name in cells:
                            yield ("ref", name)
            else:
                yield argument

    memo = {}
    active = set()

    def evaluate(name):
        # Explicit continuations avoid recursion even for deep formulas
        # and reference chains passing through every cell.
        tasks = [("cell", name)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                current = task[1]
                if current not in cells:
                    values.append(0)
                elif current in memo:
                    values.append(memo[current])
                elif current in active:
                    values.append("#CYCLE!")
                else:
                    active.add(current)
                    content = cells[current].strip()
                    node = (
                        parse(content[1:])
                        if content.startswith("=")
                        else integer(content)
                    )
                    tasks.append(("finish", current))
                    tasks.append(("node", node))

            elif kind == "finish":
                current = task[1]
                memo[current] = values[-1]
                active.remove(current)

            elif kind == "node":
                node = task[1]
                if isinstance(node, int):
                    values.append(node)
                    continue

                op = node[0]
                if op == "ref":
                    tasks.append(("cell", node[1]))
                elif op == "neg":
                    tasks.append(("negate",))
                    tasks.append(("node", node[1]))
                elif op == "IF":
                    condition, then_branch, else_branch = node[1]
                    tasks.append(("choose", then_branch, else_branch))
                    tasks.append(("node", condition))
                elif op in functions:
                    iterator = argument_nodes(node[1])
                    tasks.append(("aggregate_next", op, iterator, None))
                else:
                    tasks.append(("left_done", op, node[2]))
                    tasks.append(("node", node[1]))

            elif kind == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "left_done":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right_done", task[1], left))
                    tasks.append(("node", task[2]))

            elif kind == "right_done":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                    continue

                op, left = task[1], task[2]
                if op == "+":
                    result = left + right
                elif op == "-":
                    result = left - right
                elif op == "*":
                    result = left * right
                elif op == "/":
                    if right == 0:
                        result = "#DIV/0!"
                    else:
                        result = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            result = -result
                elif op == "=":
                    result = left == right
                elif op == "<>":
                    result = left != right
                elif op == "<":
                    result = left < right
                elif op == "<=":
                    result = left <= right
                elif op == ">":
                    result = left > right
                else:  # >=
                    result = left >= right
                values.append(result)

            elif kind == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    branch = task[1] if condition else task[2]
                    tasks.append(("node", branch))

            elif kind == "aggregate_next":
                op, iterator, accumulated = task[1:]
                node = next(iterator, None)
                if node is None:
                    values.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(
                        ("aggregate_value", op, iterator, accumulated)
                    )
                    tasks.append(("node", node))

            elif kind == "aggregate_value":
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                op, iterator, accumulated = task[1:]
                if accumulated is None:
                    accumulated = value
                elif op == "SUM":
                    accumulated += value
                elif op == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)
                tasks.append(
                    ("aggregate_next", op, iterator, accumulated)
                )

        return values.pop()

    return {name: evaluate(name) for name in cells}
